 (6,((0,0),(0,2),(1,1),(2,1))):('D',2),
}
def classify(c):
    cells=tuple((i,j) for i in range(3) for j in range(3) if c[i][j]!=0)
    col=c[cells[0][0]][cells[0][1]]
    return col, GLYPHS[(col,cells)]

def transform(grid):
    H=len(grid); W=len(grid[0])
    div=grid[0].index(4)
    out=[[0]*(W-div-1) for _ in range(H)]
    # find 5
    for i,row in enumerate(grid):
        for j in range(div+1,W):
            if row[j]==5: out[i][j-div-1]=5; start=(i,j-div-1)
    # collect glyphs: left col block cols0-2, right block cols4-6, rows of 3
    lefts=[];rights=[]
    for r0 in range(0,H-2,4):
        for base,store in ((0,lefts),(4,rights)):
            blk=[row[base:base+3] for row in grid[r0:r0+3]]
            if any(any(x) for row in blk for x in row):
                store.append(classify(blk))
    pen=(1,start[1])
    for col,dr in lefts+rights:
        d,L=dr; r,c=pen
        if d=='R':
            for k in range(L): out[r][c+k]=col
            pen=(r+1,c+L-1)
        elif d=='L':
            for k in range(L): out[r][c-k]=col
            pen=(r+1,c-L+1)
        else:
            for k in range(L): out[r+k][c]=col
            pen=(r+L,c)
    return out

